CREATE PROCEDURE [dbo].[Company_Create]
    @CompanyName        NVARCHAR(200),
    @Description        NVARCHAR(1000) = NULL,
    @Address            NVARCHAR(1000) = NULL,
    @CityId             UNIQUEIDENTIFIER,
    @StateId            UNIQUEIDENTIFIER,
    @CountryId          UNIQUEIDENTIFIER,
    @ZipCode            NVARCHAR(50) = NULL,
    @Email              NVARCHAR(320) = NULL,
    @IsActive           BIT,
    @CreatedBy          UNIQUEIDENTIFIER,
    @EstablishmentYear  NVARCHAR(20) = NULL,
    @JudistrictionArea  UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @NewId UNIQUEIDENTIFIER = NEWID();

    INSERT INTO dbo.CompanyMaster
    (
        Id,
        CompanyName,
        Description,
        Address,
        CityId,
        StateId,
        CountryId,
        ZipCode,
        Email,
        IsActive,
        IsDeleted,
        CreatedBy,
        CreatedDate,
        EstablishmentYear,
        JudistrictionArea,
        Status,
        StatusMessage
    )
    VALUES
    (
        @NewId,
        @CompanyName,
        @Description,
        @Address,
        @CityId,
        @StateId,
        @CountryId,
        @ZipCode,
        @Email,
        @IsActive,
        0,                    -- IsDeleted
        @CreatedBy,
        SYSUTCDATETIME(),     -- CreatedDate
        @EstablishmentYear,
        @JudistrictionArea,
        NULL,                 -- Status
        NULL                  -- StatusMessage
    );

    -- Return code and the new Id as a result set
    SELECT @NewId AS Id;
    RETURN 1;
END
GO
