CREATE PROCEDURE [dbo].[Company_Delete]
    @Id UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM dbo.CompanyMaster WITH (NOLOCK) WHERE Id = @Id AND IsDeleted = 0)
    BEGIN
        RETURN 0;
    END

    UPDATE dbo.CompanyMaster
    SET
        IsDeleted = 1,
        ModifiedDate = SYSUTCDATETIME()
    WHERE Id = @Id;

    RETURN 1;
END
