create  PROCEDURE [dbo].[DeleteUserDetails]
    @Id as Uniqueidentifier,
    @UserId as uniqueidentifier
AS
BEGIN
    SET NOCOUNT ON;
    update UserDetails 
        set 
        IsActive = 0,
        IsDeleted = 1,
        ModifiedBy = @UserId,
        ModifiedDate = getdate(),
        Status = 'INC',
        StatusMessage = 'User Deleted Successfully'
    where Id = @Id
    
END
