create  PROCEDURE [dbo].[GetUserFullName]
    @userName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    
    -- Get user's authentication data
    SELECT isnull(FirstName,'') + ' ' + isnull(LastName,'')        
    FROM UserDetails 
    WHERE UserName = @userName 
        AND IsActive = 1
        AND IsDeleted = 0
    
END
