CREATE PROCEDURE [dbo].[HolidayMaster_Create]
    @Name NVARCHAR(150),
    @Description NVARCHAR(250),
    @TypeId UNIQUEIDENTIFIER,
    @FromDate DATETIME,
    @ToDate DATETIME,
    @Year UNIQUEIDENTIFIER,
    @CompanyId UNIQUEIDENTIFIER,
    @SchoolId UNIQUEIDENTIFIER,
    @IsStaffApplicable BIT,
    @SessionId UNIQUEIDENTIFIER,
    @IsActive BIT,
    @CreatedBy UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @NewId UNIQUEIDENTIFIER = NEWID();

    INSERT INTO [dbo].[HolidayMaster]
    (
        Id,
        [Name],
        [Description],
        TypeId,
        FromDate,
        ToDate,
        [Year],
        CompanyId,
        SchoolId,
        IsStaffApplicable,
        SessionId,
        IsActive,
        IsDeleted,
        CreatedBy,
        CreatedDate,
        [Status],
        StatusMessage
    )
    VALUES
    (
        @NewId,
        @Name,
        @Description,
        @TypeId,
        @FromDate,
        @ToDate,
        @Year,
        @CompanyId,
        @SchoolId,
        @IsStaffApplicable,
        @SessionId,
        @IsActive,
        0,
        @CreatedBy,
        SYSUTCDATETIME(),
        N'',
        N''
    );

    SELECT Id = @NewId;
END
