/****** Object:  StoredProcedure [dbo].[RoleMaster_Create]    Script Date: 05-11-2025 23:04:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[RoleMaster_Create]
    @Name NVARCHAR(100),
    @Description NVARCHAR(500) = NULL,
    @IsActive BIT = 1,
    @CompanyId UNIQUEIDENTIFIER,
    @SchoolId UNIQUEIDENTIFIER,
    @CreatedBy UNIQUEIDENTIFIER,
    @CreatedDate DATETIME
AS
BEGIN
    SET NOCOUNT ON;
    
    DECLARE @Id UNIQUEIDENTIFIER = NEWID();
    DECLARE @IsDeleted BIT = 0;
    
    -- Check if role with same name already exists
    IF EXISTS (SELECT 1 FROM RoleMaster WHERE Name = @Name AND IsDeleted = 0)
    BEGIN
        -- Return empty result set to indicate failure
        SELECT CAST(NULL AS UNIQUEIDENTIFIER) AS Id;
        RETURN -1; -- Or appropriate error code
    END
    
    BEGIN TRY
        BEGIN TRANSACTION;
        
        -- Insert the new role
        INSERT INTO RoleMaster (
            Id,
            Name,
            Description,
            IsActive,
            IsDeleted,
            CompanyId,
            SchoolId,
            CreatedBy,
            CreatedDate
        ) VALUES (
            @Id,
            @Name,
            @Description,
            @IsActive,
            @IsDeleted,
            @CompanyId,
            @SchoolId,
            @CreatedBy,
            @CreatedDate
        );
        
        -- Return the new role ID
        SELECT @Id AS Id;
        
        COMMIT TRANSACTION;
        RETURN 1; -- Success
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
            
        -- Re-throw the error
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[RoleMaster_Delete]    Script Date: 05-11-2025 23:04:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[RoleMaster_Delete]
    @Id UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;
    
    -- Check if role exists and is not deleted
    IF NOT EXISTS (SELECT 1 FROM RoleMaster WHERE Id = @Id AND IsDeleted = 0)
    BEGIN
        RETURN 0; -- Not found or already deleted
    END
    
    BEGIN TRY
        -- Soft delete
        UPDATE 
            RoleMaster
        SET 
            IsDeleted = 1,
            ModifiedDate = GETUTCDATE()
        WHERE 
            Id = @Id;
            
        RETURN 1; -- Success
    END TRY
    BEGIN CATCH
        RETURN 0; -- Error
    END CATCH
END
GO
