/****** Object:  StoredProcedure [dbo].[RoleMaster_Update]    Script Date: 05-11-2025 23:04:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[RoleMaster_Update]
    @Id UNIQUEIDENTIFIER,
    @RoleName NVARCHAR(100),
    @Description NVARCHAR(500) = NULL,
    @IsActive BIT,
    @ModifiedBy UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;
    
    -- Check if role exists
    IF NOT EXISTS (SELECT 1 FROM RoleMaster WHERE Id = @Id AND IsDeleted = 0)
    BEGIN
        RETURN 0; -- Not found
    END
    
    -- Check if another role with the same name exists
    IF EXISTS (SELECT 1 FROM RoleMaster WHERE Id <> @Id AND Name = @RoleName AND IsDeleted = 0)
    BEGIN
        RETURN 0; -- Duplicate name
    END
    
    BEGIN TRY
        UPDATE 
            RoleMaster
        SET 
            Name = @RoleName,
            Description = @Description,
            IsActive = @IsActive,
            ModifiedBy = @ModifiedBy,
            ModifiedDate = GETUTCDATE()
        WHERE 
            Id = @Id;
            
        RETURN 1; -- Success
    END TRY
    BEGIN CATCH
        RETURN 0; -- Error
    END CATCH
END
GO
