/****** Object:  StoredProcedure [dbo].[sp_Privilege_Create]    Script Date: 05-11-2025 23:04:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[sp_Privilege_Create]
    @Id UNIQUEIDENTIFIER,
    @PrivilegeName NVARCHAR(100),
    @IsActive BIT = 1,
    @CreatedBy UNIQUEIDENTIFIER,
    @PrivilegeParentId UNIQUEIDENTIFIER = NULL
AS
BEGIN
    SET NOCOUNT ON;
    
    BEGIN TRY
        SET @Id = ISNULL(@Id, NEWID());
        
        IF NOT EXISTS (SELECT 1 FROM Privileges WHERE PrivilegeName = @PrivilegeName AND IsDeleted = 0)
        BEGIN
            INSERT INTO Privileges (
                Id,
                PrivilegeName,
                IsActive,
                CreatedBy,
                CreatedDate,
                Status,
                StatusMessage,
                PrivilegeParentId
            ) VALUES (
                @Id,
                @PrivilegeName,
                @IsActive,
                @CreatedBy,
                GETUTCDATE(),
                'COM',
                'Privilege created successfully',
                @PrivilegeParentId
            );
            
            SELECT @Id AS Id;
        END
        ELSE
        BEGIN
            SELECT CAST('00000000-0000-0000-0000-000000000000' AS UNIQUEIDENTIFIER) AS Id;
        END
    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
        RETURN -1;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[sp_Privilege_Delete]    Script Date: 05-11-2025 23:04:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[sp_Privilege_Delete]
    @Id UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;
    
    BEGIN TRY
        IF NOT EXISTS (SELECT 1 FROM Privileges WHERE Id = @Id AND IsDeleted = 0)
        BEGIN
            RETURN 0; -- Not found
        END
        
        -- Check if this privilege is being referenced by any role
        IF EXISTS (SELECT 1 FROM RolePrivileges WHERE PrivilegeId = @Id)
        BEGIN
            RETURN -1; -- In use by roles
        END
        
        -- Soft delete
        UPDATE Privileges
        SET 
            IsDeleted = 1,
            ModifiedDate = GETUTCDATE(),
            Status = 'DEL',
            StatusMessage = 'Privilege deleted'
        WHERE 
            Id = @Id;
            
        RETURN 1; -- Success
    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
        RETURN -2; -- Error
    END CATCH
END
GO
