CREATE   PROCEDURE [dbo].[sp_Privilege_GetByRoleId]
    @RoleId UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;
    
    SELECT 
        p.Id,
        p.PrivilegeName,
        p.IsActive,
        p.PrivilegeParentId,
        rp.RoleId,
        rp.IsActive AS IsAssigned
    FROM 
        Privileges p
    LEFT JOIN 
        RolePrivileges rp ON p.Id = rp.PrivilegeId AND rp.RoleId = @RoleId
    WHERE 
        p.IsDeleted = 0
    ORDER BY 
        p.PrivilegeName;
