AS
BEGIN
    SET NOCOUNT ON;
    
    SELECT 
        rp.Id,
        rp.RoleId,
        rp.PrivilegeId,
        p.PrivilegeName,
        rp.IsActive
    FROM 
        RolePrivileges rp
    INNER JOIN 
        Privileges p ON rp.PrivilegeId = p.Id
    WHERE 
        rp.RoleId = @RoleId
        AND rp.IsDeleted = 0
        AND p.IsDeleted = 0;
