/****** Object:  StoredProcedure [dbo].[sp_RolePrivilege_Update]    Script Date: 05-11-2025 23:04:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[sp_RolePrivilege_Update]
    @RoleId UNIQUEIDENTIFIER,
    @PrivilegeIds dbo.UniqueIdentifierList READONLY,
    @ModifiedBy UNIQUEIDENTIFIER,
    @ModifiedDate DATETIME
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRANSACTION;
    BEGIN TRY
        -- Mark existing role privileges as deleted
        UPDATE RolePrivileges
        SET 
            IsDeleted = 1,
            ModifiedBy = @ModifiedBy,
            ModifiedDate = @ModifiedDate
        WHERE 
            RoleId = @RoleId
            AND IsDeleted = 0;

        -- Insert new role privileges
        INSERT INTO RolePrivileges (
            Id,
            RoleId,
            PrivilegeId,
            IsActive,
            IsDeleted,
            CreatedBy,
            CreatedDate
        )
        SELECT 
            NEWID(),
            @RoleId,
            p.Id,
            1, -- IsActive
            0, -- IsDeleted
            @ModifiedBy, -- CreatedBy
            @ModifiedDate -- CreatedDate
        FROM 
            @PrivilegeIds p
        INNER JOIN 
            Privileges priv ON p.Id = priv.Id
        WHERE 
            priv.IsDeleted = 0
            AND priv.IsActive = 1;

        COMMIT TRANSACTION;
        RETURN 1; -- Success
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
            
        THROW;
    END CATCH;
END
GO
