/****** Object:  StoredProcedure [dbo].[SubjectCategory_Create]    Script Date: 05-11-2025 23:04:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SubjectCategory_Create]
    @Name NVARCHAR(200),
    @Description NVARCHAR(500),
    @ParentId UNIQUEIDENTIFIER,
    @SubjectId UNIQUEIDENTIFIER,
    @IsActive BIT,
    @CompanyId UNIQUEIDENTIFIER,
    @SchoolId UNIQUEIDENTIFIER,
    @CreatedBy UNIQUEIDENTIFIER,
    @SessionId UNIQUEIDENTIFIER = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @NewId UNIQUEIDENTIFIER = NEWID();

    -- Fallback to latest active session if @SessionId isn't provided
    IF (@SessionId IS NULL)
    BEGIN
        SELECT TOP 1 @SessionId = Id
        FROM [dbo].[SessionMaster]
        WHERE IsActive = 1
        ORDER BY CreatedDate DESC;

        IF (@SessionId IS NULL)
        BEGIN
            SELECT TOP 1 @SessionId = Id
            FROM [dbo].[SessionMaster]
            ORDER BY CreatedDate DESC;
        END
    END

    INSERT INTO [dbo].[SubjectCategoryDetails]
    (
        Id,
        Name,
        Description,
        ParentId,
        SubjectId,
        SessionId,
        IsActive,
        IsDeleted,
        CompanyId,
        SchoolId,
        CreatedBy,
        CreatedDate,
        [Status],
        StatusMessage
    )
    VALUES
    (
        @NewId,
        @Name,
        @Description,
        @ParentId,
        @SubjectId,
        @SessionId,
        @IsActive,
        0,
        @CompanyId,
        @SchoolId,
        @CreatedBy,
        SYSUTCDATETIME(),
        N'',
        N''
    );

    SELECT Id = @NewId;
END
GO
